beforeExample:
public class MyClass {
    public void method1() {
        long l = 100L;
        Long objL = new Long(l);
        int i = 200;
        Integer objI = new Integer(i);
        double d = 3.14;
        Double objD = new Double(d);
        float f = 1.618f;
        Float objF = new Float(f);
        char c = 'A';
        Character objC = new Character(c);

        System.out.println(objL);
        System.out.println(objI);
        System.out.println(objD);
        System.out.println(objF);
        System.out.println(objC);
    }
}

afterExample:
public class MyClass {
    public void method1() {
        long l = 100L;
        Long objL = Long.valueOf(l);
        int i = 200;
        Integer objI = Integer.valueOf(i);
        double d = 3.14;
        Double objD = Double.valueOf(d);
        float f = 1.618f;
        Float objF = Float.valueOf(f);
        char c = 'A';
        Character objC = Character.valueOf(c);

        System.out.println(objL);
        System.out.println(objI);
        System.out.println(objD);
        System.out.println(objF);
        System.out.println(objC);
    }
}

negativeExample:
public class MyClass {
    public void method2() {
        // Not a primitive wrapper constructor
        java.lang.String s = new java.lang.String("test");
        java.math.BigDecimal bd = new java.math.BigDecimal(123.45);

        // Boolean is handled by separate deprecation rules, not this generic numeric/char wrapper rule
        java.lang.Boolean b = new java.lang.Boolean(true);

        System.out.println(s);
        System.out.println(bd);
        System.out.println(b);
    }
}
